-- =====================================================================================================================
-- CHUBB APAC CLAIMS PLATFORM  |  CLAIM SERVICE  |  V2__seed_data.sql   (DEMO DATA)
-- ---------------------------------------------------------------------------------------------------------------------
-- 250 motor (AUTO) and property (HOME) claims across Australia, Singapore, Hong Kong, Japan, Malaysia, New Zealand,
-- with their 500 history records and 200 notifications. Data is anchored at 2026-10-22; all timestamps are UTC.
--
-- THE STORY: a regional intake surge (typhoon and storm season) has left 100 claims waiting in the work queue; five
-- claims staff are working the rest, Sydney heaviest because it covers Australia and New Zealand; 36 older claims are settled.
--
-- EXPECTED DASHBOARD FIGURES (what /api/dashboard/* on assessment-service should show after startup; money in USD,
-- converted per market and status at the rates under DATA RULES, then summed):
--     Total claims ............ 250
--     Pending claims .......... 168  (SUBMITTED + UNDER_REVIEW + MORE_INFO_REQUIRED)
--     Approved claims ......... 28
--     Rejected claims ......... 18
--     Settled claims .......... 36
--     Unassigned (work queue) . 100
--     By status ............... SUBMITTED=100  UNDER_REVIEW=56  MORE_INFO_REQUIRED=12  APPROVED=28  REJECTED=18  SETTLED=36  
--     Liability exposure ...... 2674303.58  (SUM(claim_amount) WHERE status != SETTLED, in USD, 214 claims)
--     Settled amount (excl.) .. 480955.52
--     Exposure by status ...... SUBMITTED=850718.02  UNDER_REVIEW=1033466.04  MORE_INFO_REQUIRED=321108.51  APPROVED=273959.00  REJECTED=195052.01  
--     Claims staff workload (open = UNDER_REVIEW + MORE_INFO_REQUIRED):
--        id 2 Olivia Bennett  open=20  (review 18, awaiting info 2)  approved=12  rejected=5   settled=16  total=53  open exposure=206317.01
--        id 3 Kenji Sato      open=14  (review 12, awaiting info 2)  approved=3   rejected=4   settled=2   total=23  open exposure=563285.00
--        id 4 Mei Lin Chua    open=17  (review 12, awaiting info 5)  approved=3   rejected=4   settled=6   total=30  open exposure=425235.53
--        id 5 Rajesh Kumar    open=10  (review 8, awaiting info 2)  approved=6   rejected=3   settled=4   total=23  open exposure=60262.50
--        id 6 Grace Wong      open=7   (review 6, awaiting info 1)  approved=4   rejected=2   settled=8   total=21  open exposure=99474.50
--     Exposure by market (claims counted, own currency, USD):
--        AU   61 claims   969,380.25 AUD   646,253.50 USD
--        HK   21 claims  2,447,203.20 HKD   313,744.00 USD
--        JP   37 claims 90,401,325 JPY      602,675.50 USD
--        MY   30 claims   893,641.50 MYR   198,587.00 USD
--        NZ   20 claims   426,171.12 NZD   258,285.52 USD
--        SG   45 claims   883,923.38 SGD   654,758.06 USD
--     Claims by country (motor/property):
--        Australia     70  (46 motor / 24 property)
--        Hong Kong     30  (14 motor / 16 property)
--        Japan         40  (18 motor / 22 property)
--        Malaysia      35  (22 motor / 13 property)
--        New Zealand   25  (14 motor / 11 property)
--        Singapore     50  (32 motor / 18 property)
--
-- DATA RULES
--   * Each claim is in the currency of its market (AU AUD, HK HKD, JP JPY, MY MYR, NZ NZD, SG SGD). The amounts were first
--     drawn as USD-equivalents and then converted at the same indicative fixed rates assessment-service uses to report in
--     USD (per 1 USD: AUD 1.50, HKD 7.80, JPY 150, MYR 4.50, NZD 1.65, SGD 1.35), so the USD figures in this header survive
--     the round trip to within rounding. JPY has no minor unit, so yen amounts are whole numbers.
--   * market is the two-letter country code and always equals the second segment of the policy number (MTR-SG-2024-...),
--     so the 250 claims split AU 70, HK 30, JP 40, MY 35, NZ 25, SG 50 (the "Claims by country" table above).
--   * Claim numbers follow the application's own scheme CLM-<year>-<global 6-digit sequence>; the sequence is moved
--     on at the end so the next claim submitted through the API is CLM-2026-000251.
--   * claimant_id / assigned_staff_id are auth-service user ids (claimants 7..26, claims staff 2..6).
--   * A claim is unassigned exactly while SUBMITTED. Every other claim has an assigned staff member and exactly one row in
--     assessment-service's claim_assessments (150 of them, same claim ids).
--   * Settlement is not an event the platform records yet (no settle endpoint), so a SETTLED claim's history ends at
--     its approval; claims.updated_at carries the settlement time.
--   * To start with an EMPTY platform instead, skip this file: set FLYWAY_TARGET=1 (spring.flyway.target).
-- =====================================================================================================================

-- ---------------------------------------------------------------------------------------------------------------------
-- claims (250). Ordered by submission time, so ids and claim numbers rise with time.
-- ---------------------------------------------------------------------------------------------------------------------










-- ---------------------------------------------------------------------------------------------------------------------
-- claim_history (500): CLAIM_CREATED for every claim, CLAIM_ASSIGNED for the 150 taken by a claims staff member,
-- plus decisions and information requests/replies, in the order they happened.
-- ---------------------------------------------------------------------------------------------------------------------




















-- ---------------------------------------------------------------------------------------------------------------------
-- notifications (200): the most recent notifications; older ones are assumed archived. Recent ones are still unread.
-- ---------------------------------------------------------------------------------------------------------------------








-- ---------------------------------------------------------------------------------------------------------------------
-- Ids were inserted explicitly, so move the counters past them: the next claim is id 251 / CLM-2026-000251.
-- ---------------------------------------------------------------------------------------------------------------------
ALTER TABLE claims ALTER COLUMN id RESTART WITH 251;
ALTER TABLE claim_history ALTER COLUMN id RESTART WITH 501;
ALTER TABLE notifications ALTER COLUMN id RESTART WITH 201;
ALTER SEQUENCE claim_number_seq RESTART WITH 251;
